//! Item categories that chest names refer to ("Food", "Ores, Gems", "Wood + Stone"),
//! shared by the mods: chestsort sorts quick stacks by them, the assistants put their
//! results where they belong. Also the item id -> debug name table ([`ITEM_NAMES`]).
//!
//! The categories live in `chestsort_categories.json` next to the server
//! executable, which is created from the built-in defaults (`categories.json`,
//! generated by research/scripts/categorize.py) when missing. Items are listed by
//! debug name and resolved through the embedded `items.tsv`; the file is
//! re-read whenever it changes, so edits apply without a restart.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::PathBuf;
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant, SystemTime};

use shroudlink_sdk::log;
use serde::Deserialize;

const DEFAULT_FILE: &str = include_str!("../categories.json");
/// `item id <tab> debug name` for every item of the game build the mods target.
pub const ITEM_NAMES: &str = include_str!("../items.tsv");
const FILE_NAME: &str = "chestsort_categories.json";
/// How often a deposit may look at the file's modification time.
const RELOAD_CHECK: Duration = Duration::from_secs(2);

#[derive(Deserialize)]
struct File {
    categories: BTreeMap<String, CategoryDef>,
}

#[derive(Deserialize)]
struct CategoryDef {
    #[serde(default)]
    words: Vec<String>,
    #[serde(default)]
    items: Vec<String>,
}

struct Categories {
    /// lower-case chest-name word -> category names
    words: HashMap<String, Vec<String>>,
    items: HashMap<String, HashSet<u32>>,
    /// chest name -> accepted item ids
    cache: Mutex<HashMap<String, HashSet<u32>>>,
}

struct State {
    current: Arc<Categories>,
    modified: Option<SystemTime>,
    checked: Instant,
}

static STATE: Mutex<Option<State>> = Mutex::new(None);

fn path() -> PathBuf {
    shroudlink_sdk::server_dir().join(FILE_NAME)
}

fn modified() -> Option<SystemTime> {
    std::fs::metadata(path()).and_then(|m| m.modified()).ok()
}

/// Loads the category file (creating it with the defaults if needed); call once at startup.
pub fn init() {
    current();
}

fn current() -> Arc<Categories> {
    let mut guard = STATE.lock().unwrap();
    match guard.as_mut() {
        None => {
            if !path().exists() {
                match std::fs::write(path(), DEFAULT_FILE) {
                    Ok(()) => log!("created {FILE_NAME} with the default categories"),
                    Err(e) => log!("could not create {FILE_NAME} ({e})"),
                }
            }
            let current = Arc::new(load().unwrap_or_else(|e| {
                log!("{e}; using the built-in categories until the file is fixed");
                build(DEFAULT_FILE).expect("built-in categories.json is valid")
            }));
            *guard = Some(State { current, modified: modified(), checked: Instant::now() });
        }
        Some(state) if state.checked.elapsed() >= RELOAD_CHECK => {
            state.checked = Instant::now();
            let now = modified();
            if now != state.modified {
                state.modified = now;
                match load() {
                    Ok(c) => {
                        state.current = Arc::new(c);
                        log!("reloaded {FILE_NAME}");
                    }
                    Err(e) => log!("{e}; keeping the previous categories"),
                }
            }
        }
        Some(_) => {}
    }
    guard.as_ref().unwrap().current.clone()
}

fn load() -> Result<Categories, String> {
    let text = std::fs::read_to_string(path()).map_err(|e| format!("cannot read {FILE_NAME} ({e})"))?;
    build(&text)
}

/// All items of the game: (lower-case debug name, id).
fn item_names() -> &'static [(String, u32)] {
    static NAMES: OnceLock<Vec<(String, u32)>> = OnceLock::new();
    NAMES.get_or_init(|| {
        ITEM_NAMES
            .lines()
            .filter_map(|line| {
                let (id, name) = line.split_once('\t')?;
                Some((name.to_lowercase(), id.parse().ok()?))
            })
            .collect()
    })
}

/// Case-insensitive match with `*` as wildcard; both arguments lower case.
fn wildcard_match(pattern: &str, text: &str) -> bool {
    let parts: Vec<&str> = pattern.split('*').collect();
    if parts.len() == 1 {
        return pattern == text;
    }
    let (first, last) = (parts[0], parts[parts.len() - 1]);
    if !text.starts_with(first) || text.len() < first.len() + last.len() || !text.ends_with(last) {
        return false;
    }
    let mut rest = &text[first.len()..text.len() - last.len()];
    for part in &parts[1..parts.len() - 1] {
        match rest.find(part) {
            Some(i) => rest = &rest[i + part.len()..],
            None => return false,
        }
    }
    true
}

/// Item ids for one `items` entry: a debug name, a `*` pattern or a plain item id.
fn resolve(entry: &str) -> Vec<u32> {
    if let Ok(id) = entry.parse::<u32>() {
        return vec![id];
    }
    let entry = entry.to_lowercase();
    item_names()
        .iter()
        .filter(|(name, _)| wildcard_match(&entry, name))
        .map(|&(_, id)| id)
        .collect()
}

fn build(text: &str) -> Result<Categories, String> {
    let file: File = serde_json::from_str(text).map_err(|e| format!("{FILE_NAME} is invalid ({e})"))?;
    let mut words: HashMap<String, Vec<String>> = HashMap::new();
    let mut items = HashMap::new();
    let mut unknown = Vec::new();
    for (category, def) in &file.categories {
        let mut set = HashSet::new();
        for entry in def.items.iter().map(|e| e.trim()).filter(|e| !e.is_empty()) {
            let (remove, pattern) = match entry.strip_prefix('-') {
                Some(p) => (true, p.trim()),
                None => (false, entry),
            };
            let ids = resolve(pattern);
            if ids.is_empty() {
                unknown.push(format!("{category}: {entry}"));
            }
            for id in ids {
                if remove {
                    set.remove(&id);
                } else {
                    set.insert(id);
                }
            }
        }
        items.insert(category.clone(), set);
        for word in std::iter::once(category).chain(&def.words) {
            let word = word.trim().to_lowercase();
            if word.is_empty() {
                continue;
            }
            let targets = words.entry(word).or_default();
            if !targets.contains(category) {
                targets.push(category.clone());
            }
        }
    }
    // "Ore" works like "Ores" unless "ore" means something else on its own
    let singulars: Vec<(String, Vec<String>)> = words
        .iter()
        .filter(|(w, _)| w.len() > 3 && w.ends_with('s'))
        .map(|(w, t)| (w[..w.len() - 1].to_owned(), t.clone()))
        .collect();
    for (word, targets) in singulars {
        words.entry(word).or_insert(targets);
    }

    let summary: Vec<String> = file.categories.keys().map(|c| format!("{c} {}", items[c].len())).collect();
    log!("categories: {}", summary.join(", "));
    if !unknown.is_empty() {
        log!("{} item entr(ies) match no item: {}", unknown.len(), unknown.join("; "));
    }
    Ok(Categories { words, items, cache: Mutex::new(HashMap::new()) })
}

/// Item ids whose debug name contains every word of `query` (case-insensitive), at most `limit`.
pub fn search(query: &str, limit: usize) -> Vec<u32> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    if words.is_empty() {
        return Vec::new();
    }
    item_names()
        .iter()
        .filter(|(name, _)| words.iter().all(|w| name.contains(w.as_str())))
        .map(|&(_, id)| id)
        .take(limit)
        .collect()
}

/// Overview for UIs: every category with the chest-name words that select it and its item ids.
pub fn overview() -> Vec<(String, Vec<String>, Vec<u32>)> {
    let cats = current();
    let mut list: Vec<(String, Vec<String>, Vec<u32>)> = cats
        .items
        .iter()
        .map(|(name, ids)| {
            let mut words: Vec<String> = cats.words.iter().filter(|(_, t)| t.contains(name)).map(|(w, _)| w.clone()).collect();
            words.sort();
            let mut ids: Vec<u32> = ids.iter().copied().collect();
            ids.sort();
            (name.clone(), words, ids)
        })
        .collect();
    list.sort_by(|a, b| a.0.cmp(&b.0));
    list
}

/// Category names mentioned in a chest name, e.g. "Ores & Gems" -> ["Ores", "Gems"].
pub fn parse(name: &str) -> Vec<String> {
    parse_with(&current(), name)
}

fn parse_with(cats: &Categories, name: &str) -> Vec<String> {
    let mut result: Vec<String> = Vec::new();
    for word in name.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()) {
        if let Some(targets) = cats.words.get(&word.to_lowercase()) {
            for t in targets {
                if !result.contains(t) {
                    result.push(t.clone());
                }
            }
        }
    }
    result
}

/// Item ids accepted by a chest with this name (empty if the name has no category words).
pub fn items_for(name: &str) -> HashSet<u32> {
    let cats = current();
    let mut cache = cats.cache.lock().unwrap();
    if let Some(items) = cache.get(name) {
        return items.clone();
    }
    let items: HashSet<u32> = parse_with(&cats, name)
        .iter()
        .filter_map(|c| cats.items.get(c))
        .flat_map(|set| set.iter().copied())
        .collect();
    cache.insert(name.to_owned(), items.clone());
    items
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wildcards() {
        assert!(wildcard_match("food_t1_*", "food_t1_raw_mushroom"));
        assert!(wildcard_match("*_seedling", "plant_seedling"));
        assert!(wildcard_match("*ore*", "material_t2_ore_iron"));
        assert!(wildcard_match("a*b*c", "abc"));
        assert!(!wildcard_match("a*b*c", "ac"));
        assert!(!wildcard_match("ab*ba", "aba"));
        assert!(!wildcard_match("food", "food_x"));
    }

    #[test]
    fn defaults_resolve() {
        let cats = build(DEFAULT_FILE).unwrap();
        assert_eq!(cats.items["Food"].len(), 208);
        assert_eq!(cats.items["Decor"].len(), 1269);
        assert_eq!(parse_with(&cats, "food, Wood"), ["Food", "Wood"]);
        assert_eq!(parse_with(&cats, "Ore"), ["Ores"]);
        let materials = parse_with(&cats, "Materials");
        assert_eq!(materials.len(), 9);
        assert!(!materials.contains(&"Misc".to_owned()));
        assert_eq!(parse_with(&cats, "Keys"), ["Misc"]);
        let lockpick = resolve("Lockpick_Scrapy_T0-T4")[0];
        assert!(cats.items.values().all(|set| !set.contains(&lockpick)));
        let castle_key = resolve("Key_Gold02_Castle")[0];
        assert!(cats.items["Misc"].contains(&castle_key));
        assert!(parse_with(&cats, "BJCK").is_empty());
    }

    #[test]
    fn removal_and_ids() {
        let cats = build(r#"{"categories":{"Mush":{"words":["shrooms"],"items":["*mushroom*","-*_raw_*","123"]}}}"#).unwrap();
        let ids = &cats.items["Mush"];
        assert!(ids.contains(&123));
        let raw = resolve("Food_T1_raw_mushroom_Mushroom_brown")[0];
        assert!(!ids.contains(&raw));
        assert_eq!(parse_with(&cats, "Shrooms"), ["Mush"]);
    }
}
